<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';const props=defineProps({settings:Object});const form=reactive({...props.settings});function save(){router.patch('/admin/settings',form);}</script>
<template><Layout><p class="eyebrow">Brand & store</p><h1 class="serif text-5xl font-bold">Settings</h1><div class="card mt-6 grid gap-4"><label>Instagram<input v-model="form.instagram" class="field mt-1" placeholder="https://instagram.com/..."/></label><label>TikTok<input v-model="form.tiktok" class="field mt-1" placeholder="https://tiktok.com/@..."/></label><label>WhatsApp<input v-model="form.whatsapp" class="field mt-1" placeholder="2010..."/></label><label>Free delivery threshold<input v-model="form.free_delivery_threshold" class="field mt-1"/></label><label>Brand tagline<input v-model="form.brand_tagline" class="field mt-1"/></label><button @click="save" class="pill dark w-fit">Save changes</button></div></Layout></template>
